const manual={enabled:true,index:0,history:[],message:''};
const movePanel=el('section',{class:'panel manual-tools','aria-label':'Manual part placement'});
movePanel.innerHTML='<div class="sectionhead"><label class="move-toggle"><input id="move-mode" type="checkbox"> Move parts</label></div><p class="hint">After optimizing, drag a piece on this sheet, or select it and enter an exact position in cm. Arrow keys move 1 mm; Shift + arrow moves 1 cm.</p><div id="move-fields"><label>Part<select id="move-part"></select></label><label>X (cm)<input id="move-x" type="number" min="0" step="0.1"></label><label>Y (cm)<input id="move-y" type="number" min="0" step="0.1"></label><button id="apply-move">Move</button></div><div class="tool-buttons"><button id="undo-move">Undo move</button><button id="reset-layout">Reset to automatic layout</button></div><p id="move-message" class="hint" role="status"></p>';
movePanel.hidden=true;
$('diagram').before(movePanel);
function layoutSignature(){return JSON.stringify([state.stock,state.parts,state.kerf,state.rotate]);}
function storeManual(){state.manualLayout={signature:layoutSignature(),result:JSON.parse(JSON.stringify(result))};try{localStorage.setItem('sheetwise',JSON.stringify(state));}catch{manual.message+=' Browser storage is full; save a project file to keep these adjustments.';}}
function selectManualPart(index){manual.index=index;const s=result.sheets[selected],p=s?.pieces[index];if(p){$('move-part').value=index;$('move-x').value=dimension(p.x);$('move-y').value=dimension(p.y);}document.querySelectorAll('#diagram .cut-part').forEach((node,i)=>node.classList.toggle('move-selected',manual.enabled&&i===index));}
function renderManual(){const s=result?.sheets[selected],enabled=manual.enabled&&!dirty&&!!s;$('move-mode').checked=manual.enabled;$('move-part').replaceChildren();s?.pieces.forEach((p,i)=>$('move-part').append(el('option',{value:i},(i+1)+'. '+p.label+' · '+dimension(p.w)+' × '+dimension(p.h)+' cm')));if(!s?.pieces[manual.index])manual.index=0;for(const id of ['move-part','move-x','move-y','apply-move'])$(id).disabled=!enabled;$('undo-move').disabled=dirty||!manual.history.length;$('reset-layout').disabled=!state.manualLayout;$('move-message').textContent=dirty?'Inputs changed. Optimize again before moving parts.':manual.message||'Moves stay on the current sheet. Overlaps, saw kerf and straight-cut access are checked.';selectManualPart(manual.index);$('diagram').classList.toggle('move-enabled',enabled);if(enabled)bindManualDrag();}
function applyManualMove(x,y){if(!manual.enabled||dirty)return;const sheet=result.sheets[selected],p=sheet?.pieces[manual.index];if(!p)return;if(Math.abs(x-p.x)<1e-7&&Math.abs(y-p.y)<1e-7)return;const proposed=ManualGeometry.proposeMove(sheet,manual.index,x,y,state.kerf);if(proposed.error){manual.message=proposed.error;renderManual();return false;}manual.history.push({sheet:selected,before:JSON.parse(JSON.stringify(sheet))});if(manual.history.length>40)manual.history.shift();proposed.sheet.pieces.forEach(piece=>piece.done=false);result.sheets[selected]=proposed.sheet;manual.message='Moved '+p.label+' to X '+dimension(x)+', Y '+dimension(y)+' cm. Layout checked.';$('status').textContent='Manually adjusted layout · '+result.sheets.reduce((t,s)=>t+s.pieces.length,0)+' pieces placed · Optimize again to replace manual changes.';storeManual();draw();return true;}
function snapMove(sheet,index,x,y){const p=sheet.pieces[index],threshold=Math.min(1,sheet.w*.006),xs=[0,sheet.w-p.w],ys=[0,sheet.h-p.h];sheet.pieces.forEach((q,i)=>{if(i===index)return;xs.push(q.x,q.x+q.w-p.w,q.x+q.w+state.kerf,q.x-p.w-state.kerf);ys.push(q.y,q.y+q.h-p.h,q.y+q.h+state.kerf,q.y-p.h-state.kerf);});const snap=(v,targets)=>{let best=Math.round(v*10)/10,distance=threshold;for(const t of targets)if(Math.abs(t-v)<distance){best=t;distance=Math.abs(t-v);}return Math.round(best*100000)/100000;};return {x:snap(x,xs),y:snap(y,ys)};}
function bindManualDrag(){const svg=$('diagram').querySelector('svg'),s=result.sheets[selected];if(!svg)return;svg.querySelectorAll('.cut-part').forEach((node,index)=>{node.setAttribute('role','button');node.setAttribute('aria-label','Move '+s.pieces[index].label+' piece '+(index+1));node.onkeydown=event=>{const offsets={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(!offsets[event.key])return;event.preventDefault();selectManualPart(index);const p=result.sheets[selected].pieces[index],step=event.shiftKey?1:.1,[dx,dy]=offsets[event.key];applyManualMove(Math.round((p.x+dx*step)*100000)/100000,Math.round((p.y+dy*step)*100000)/100000);};node.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();selectManualPart(index);const point=event=>{const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());},origin=point(event),p=s.pieces[index],ghost=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [k,v]of Object.entries({x:p.x,y:p.y,width:p.w,height:p.h,class:'move-ghost','pointer-events':'none'}))ghost.setAttribute(k,v);svg.append(ghost);node.setPointerCapture(event.pointerId);let target={x:p.x,y:p.y},dragged=false;const move=e=>{if(Math.hypot(e.clientX-event.clientX,e.clientY-event.clientY)>2)dragged=true;const at=point(e);target=snapMove(s,index,p.x+at.x-origin.x,p.y+at.y-origin.y);ghost.setAttribute('x',target.x);ghost.setAttribute('y',target.y);ghost.classList.toggle('invalid',!!ManualGeometry.validatePosition(s,index,target.x,target.y,state.kerf));$('move-x').value=dimension(target.x);$('move-y').value=dimension(target.y);};const cleanup=()=>{ghost.remove();node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',cancel);};const up=e=>{move(e);cleanup();if(dragged)applyManualMove(target.x,target.y);selectManualPart(index);};const cancel=()=>{cleanup();selectManualPart(index);};node.addEventListener('pointermove',move);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',cancel);};});}
$('move-mode').onchange=()=>{manual.enabled=$('move-mode').checked;draw();};$('move-part').onchange=()=>selectManualPart(Number($('move-part').value));$('apply-move').onclick=()=>applyManualMove(Number($('move-x').value),Number($('move-y').value));
$('undo-move').onclick=()=>{if(dirty)return;const previous=manual.history.pop();if(!previous)return;result.sheets[previous.sheet]=previous.before;selected=previous.sheet;manual.message='Last move undone.';storeManual();draw();};
$('reset-layout').onclick=()=>run();
function restoreManualLayout(){const saved=state.manualLayout;if(!saved||saved.signature!==layoutSignature())return false;try{const candidate=saved.result;if(candidate.sheets.length!==result.sheets.length)return false;for(let i=0;i<result.sheets.length;i++){const a=result.sheets[i],b=candidate.sheets[i];if(a.w!==b.w||a.h!==b.h||a.pieces.length!==b.pieces.length)return false;for(let j=0;j<a.pieces.length;j++){const p=a.pieces[j],q=b.pieces[j];if(p.id!==q.id||p.w!==q.w||p.h!==q.h||ManualGeometry.validatePosition(b,j,q.x,q.y,state.kerf))return false;}const free=ManualGeometry.partitionSheet(b,state.kerf);if(free===null)return false;b.free=free;}result.sheets=candidate.sheets;manual.message='Restored your manually adjusted layout.';$('status').textContent='Manually adjusted layout restored · '+result.sheets.reduce((t,s)=>t+s.pieces.length,0)+' pieces placed';return true;}catch{return false;}}
const manualDraw=draw;draw=function(){manualDraw();renderManual();};
const manualChanged=changed;changed=function(){manualChanged();if($('move-message'))renderManual();};
const automaticRun=run;run=function(){const saved=state.manualLayout;delete state.manualLayout;const ok=automaticRun();if(!ok){if(saved)state.manualLayout=saved;return false;}manual.enabled=true;manual.history=[];manual.message='Automatic layout ready. Drag a part to adjust its position.';renderManual();return true;};$('run').onclick=()=>run();
const manualLoad=loadProject;loadProject=function(candidate){const saved=candidate.manualLayout;manualLoad(candidate);if(saved){state.manualLayout=saved;if(restoreManualLayout()){storeManual();draw();}else{delete state.manualLayout;manual.message='Project opened; saved manual positions no longer match. Automatic layout shown.';renderManual();}}};
restoreManualLayout();draw();

